                    if r['c']=='1' and (not source_safe(span) or re.search(r'\b(?:if i|if he|if she|hypothetically|suppose|would like to pretend)\b|\.\.\.|[—-]$',span.lower())): raise ValueError('unsupported assertion')
                complete=[r for r in rows if r['c']=='1'];kinds={r['k'] for r in complete}
                s['format']=0
            except Exception:
                rows=[];complete=[];kinds=set();vals={};s['format']+=1
            if not rows:
                if s['format']>3:
                    finish('no_promise' if s.get('verified') else 'not_reached','NOP-SYS' if s.get('verified') else 'NRC-NOCB','service_error' if s.get('verified') else '', 'I could not understand the arrangement, so nothing has been recorded. Please use online banking.')
                elif phase=='callback': say('Please give the day and time when the customer can be reached.')
                elif phase=='confirm': say('Please confirm whether the arrangement I just read back is correct.')
                else: say('Please clarify your request. I have not recorded an arrangement.')
            elif any(r['c']=='0' for r in rows):
                s['readback']=0
                if 'a' in vals: s['amount']=money(vals['a'])
                if 'd' in vals and vals['d']!='vague': s['date']=date_value(vals['d'],today,s.get('date','')).isoformat()
                needs={r.get('u','intent') for r in rows if r['c']=='0'}
                if 'both' in needs: needs.remove('both');needs.update(['amount','date'])
                s['needs']=list(needs)
                if 'amount' in needs or 'both' in needs: say('Take your time; I am listening.')
                elif 'date' in needs: say('Please continue with the date.')
                else: say('Please finish your request.')
            elif phase=='callback':
                if 'refuse' in kinds or 'decline' in kinds: finish('not_reached','NRC-NOCB')
                elif 'death' in kinds and source_safe(raw): finish('not_reached','NRC-DECD',text='I am very sorry to hear that.')
                elif 'wrong' in kinds: finish('not_reached','NRC-WRONG',text='I am sorry for the inconvenience.')
                elif 'accept' in kinds and s.get('callback_offer'): action('schedule_callback',dict(date=shift(today,1).isoformat(),time='10:00'))
                elif 'd' in vals and 't' in vals:
                    d=date_value(vals['d'],today);t=vals['t']
                    if not re.fullmatch(r'\d{2}:\d{2}',t): raise ValueError('time')
                    if shift(today,1)<=d<=shift(today,3) and business(d) and '09:00'<=t<='17:30': action('schedule_callback',dict(date=d.isoformat(),time=t))
                    elif not s.get('callback_offer'): s['callback_offer']=True;say('Could Nordhaven call on '+spoken(shift(today,1))+' at 10:00?')
                    else: finish('not_reached','NRC-NOCB')
                else: say('Please give the day and time when the customer can be reached.')
            elif s.get('verified') and re.search(r'no time|have to go|must go|call me later',x): finish('no_promise','NOP-RTP','refused','I understand you need to leave.')
            elif 'human' in kinds or 'plan' in kinds:
                s['transfer_reason']='TRF-HUM' if 'human' in kinds else 'TRF-RST';action('transfer_to_agent',dict(queue='general' if 'human' in kinds else 'restructuring'))
            elif 'dispute' in kinds:
                if source_safe(raw) and re.search(r'not mine|never had|closed|settled|disput|not my',x): finish('no_promise','NOP-DSP','dispute','I will have this investigated.')
                else: say('Are you saying this product is not yours, or asking about its charges?')
            elif 'paid' in kinds or phase=='paid_date':
                supported=phase=='paid_date' or (source_safe(raw) and re.search(r'\bi\b|\bi.ve\b',x) and re.search(r'\bpaid\b|made (?:the |a )?payment|processed (?:the |a )?payment',x) and not re.search(r'haven.t paid|have not paid|didn.t pay|not paid|bounced|reversed|rent|invoice|parcel|might have|not sure|will pay',x))
                if not supported: say('Are you saying you already paid this overdue amount?')
                elif 'd' not in vals: say('On which date did you pay?','paid_date')
                else:
                    d=date_value(vals['d'],today)
                    if d in (today,shift(today,-1)): finish('paid',note='paid',text='A payment can take up to two business days to show.')
                    elif d<shift(today,-1): finish('no_promise','NOP-DSP','dispute','The payment does not show on the account and will be investigated.')
                    else: say('Please confirm the date you already paid.','paid_date')
            elif 'fees' in kinds: s['resume_phase']=phase;say('Would you like me to transfer you to the support team, who can explain the charges?','support')
            elif phase=='support':
                if kinds & {'accept','confirm'} and consent(raw): s['transfer_reason']='TRF-FEE';action('transfer_to_agent',dict(queue='support'))
                elif kinds & {'refuse','decline'}:
                    s['phase']=s.get('resume_phase','offer')
                    if s['phase']=='confirm': readback()
                    else: say('Let us continue with the arrangement. Is the last proposal acceptable?')
                else: say('Would you like a transfer to the support team?')
            elif 'stop' in kinds:
                s['stops']=s.get('stops',0)+1
                if s['stops']>=2: finish('no_promise','NOP-RTP','refused')
                else: say('I understand. Do you want to end this conversation?')
            elif 'hardship' in kinds and not ('a' in vals and 'd' in vals): finish('no_promise','NOP-HSH','hardship','I am sorry you are going through this. Our hardship team will write to you within five business days.')
            elif kinds & {'propose','accept','confirm','too_much'}:
                if phase=='confirm' and kinds=={'confirm'} and not vals and consent(raw) and s.get('readback')==s.get('revision') and not s.get('needs'):
                    action('create_promise',dict(product_id=s['product']['product_id'],amount=s['amount']/100,date=s['date']));s['readback']=0
                else:
                    if phase=='confirm': s['readback']=0
                    if 'confirm' in kinds and not vals and not consent(raw): say('Please confirm whether the readback is correct.')
                    else:
                        if 'too_much' in kinds:
                            s['too_much']=True
                            if s.get('floor_offered'): refuse()
                            else: s['floor_offered']=True;offer(s['floor'],s.get('date',s['deadline']),'floor')
                        else:
                            if 'a' in vals: s['amount']=money(vals['a']);s['needs']=[n for n in s.get('needs',[]) if n not in ('amount','both')]
                            if 'd' in vals:
                                s['needs']=[n for n in s.get('needs',[]) if n not in ('date','both')]
                                if vals['d']=='vague': offer(s['amount'],s['deadline'],'deadline')
                                else:
                                    d=date_value(vals['d'],today,s.get('date',''));s['date']=d.isoformat()
                            if v['route']=='safe_end':
                                a=s.get('amount');d=datetime.date.fromisoformat(s['date']) if s.get('date') else None
                                if s.get('needs'): say('Take your time; I am listening.' if 'amount' in s['needs'] else 'Please continue with the date.')
                                elif a<s['floor']: s['floor_offered']=True;offer(s['floor'],s['date'],'low')
                                elif a>s['full']: offer(s['full'],s['date'],'amount_limit')
                                elif d is None: say('On which date can you pay this amount?','proposal')
                                elif d>datetime.date.fromisoformat(s['deadline']): offer(a,s['deadline'],'deadline')
                                elif d<today: say('That date has passed. On which date can you pay this amount?','proposal')
                                elif not business(d):
                                    alt=before(d)
                                    if alt<today: alt=shift(d,1)
                                    prefix+='That day is not possible. ';offer(a,alt.isoformat(),'calendar')
                                else: readback()
            elif kinds & {'refuse','decline','unknown'}: refuse()
            elif 'aside' in kinds: say('I am here. '+('Is the readback correct?' if phase=='confirm' else 'Is the last proposal acceptable?'))
            else: say('Please clarify your request.')
    v['state']=json.dumps(s)
    v['phase']=s['phase'];v['requested_field']=s.get('field','');v['answer_revision']=s.get('security_revision',0)
    v['offer_context']=json.dumps({k:s.get(k,'') for k in ('label','amount','date','deadline','phase','revision')})
